// Maintained actual Sandbox capture; inputs and outputs supplied by the refresh driver.
const fs=require('fs'), path=require('path'), crypto=require('crypto'), assert=require('node:assert/strict');
const {SmartContract}=require(require('./context.cjs').nativeRoot+'/node_modules/@ton/sandbox');
const {Cell,Dictionary,Address}=require(require('./context.cjs').nativeRoot+'/node_modules/@ton/core');
const {nativeRoot:repo, outputRoot:out}=require('./context.cjs');

function inventory(){const result={};function walk(r){for(const i of fs.readdirSync(path.join(repo,r),{withFileTypes:true})){const n=r+'/'+i.name;if(i.isDirectory())walk(n);else if(i.isFile())result[n]=crypto.createHash('sha256').update(fs.readFileSync(path.join(repo,n))).digest('hex');}}for(const r of ['contracts','wrappers','scripts','config','interfaces','tests','simulations'])walk(r);return Object.fromEntries(Object.entries(result).sort(([a],[b])=>a.localeCompare(b)));}
const sourceBefore=inventory();const compilerSources=new Set(JSON.parse(fs.readFileSync(path.join(out,'dependency-sources.json'),'utf8')));let rows=[];
function captureProof(){const current=inventory(),closure={};const imported=Object.keys(require.cache).filter(p=>p.startsWith(repo+'/')&&!p.startsWith(__dirname+'/')).sort();for(const [name,digest]of Object.entries(sourceBefore))if(compilerSources.has(name)||imported.includes(path.join(repo,name))){assert.equal(current[name],digest,'Capture dependency changed: '+name);closure[name]=digest;}const importedModules=Object.fromEntries(imported.map(p=>[p.slice(repo.length+1),crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')]));const runtimeFiles=Object.fromEntries([process.execPath,...['package.json','package-lock.json','tsconfig.json','jest.config.cjs'].map(p=>path.join(repo,p))].map(p=>[p,crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')]));return{sourceClosure:closure,importedModules,runtimeFiles,privateSources:[__filename,require.resolve('./context.cjs'),path.join(out,'capture-jest.config.cjs'),path.join(out,'dependency-sources.json')].map(p=>({filename:p,contents:fs.readFileSync(p,'utf8'),sha256:crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')})),unrelatedInventoryDrift:Object.keys(current).filter(k=>current[k]!==sourceBefore[k]&&!closure[k]).map(k=>({filename:k,before:sourceBefore[k]??null,after:current[k]}))};}

function state(sc){const originalShardAccount=sc._account;const account=Cell.fromBase64(originalShardAccount).refs[0];const active=sc.accountState?.type==='active'?sc.accountState.state:null;return{originalShardAccount,accountBoc:account.toBoc().toString('base64'),accountHash:account.hash().toString('hex'),balance:sc.balance.toString(),lastTxLt:sc.lastTransactionLt.toString(),lastTxHash:sc.lastTransactionHash.toString(16).padStart(64,'0'),codeBoc:active?.code?.toBoc().toString('base64')??null,dataBoc:active?.data?.toBoc().toString('base64')??null};}
function message(m,c){return{messageBoc:c.toBoc().toString('base64'),messageHash:c.hash().toString('hex'),bodyBoc:m.body.toBoc().toString('base64'),bodyHash:m.body.hash().toString('hex')};}
const original=SmartContract.prototype.receiveMessage;
SmartContract.prototype.receiveMessage=async function(...args){const before=state(this);const tx=await original.apply(this,args);const after=state(this);assert.equal(before.accountHash,tx.stateUpdate.oldHash.toString('hex'));assert.equal(after.accountHash,tx.stateUpdate.newHash.toString('hex'));const m=tx.raw.refs[0].beginParse(),incoming=m.loadBit()?m.loadRef():null,outgoing=m.loadDict(Dictionary.Keys.Uint(15),Dictionary.Values.Cell());rows.push({account:this.address.toRawString(),lt:tx.lt.toString(),hash:tx.raw.hash().toString('hex'),boc:tx.raw.toBoc().toString('base64'),utime:tx.now,prevTxLt:tx.prevTransactionLt.toString(),prevTxHash:tx.prevTransactionHash.toString(16).padStart(64,'0'),codeBoc:after.codeBoc??before.codeBoc,beforeDataBoc:before.dataBoc,afterDataBoc:after.dataBoc,before,after,incoming:tx.inMessage?message(tx.inMessage,incoming):null,outgoing:[...tx.outMessages].map(([i,msg])=>message(msg,outgoing.get(i)))});return tx;};
beforeEach(()=>{rows=[];});
afterEach(()=>{const name=expect.getState().currentTestName;if(!/(credits direct protocol fees|failed sale refunds|rejects inviter)/.test(name))return;const kind=name.match(/(Fixed|Bonding|Auction) /)?.[1].toLowerCase();const outcome=name.includes('credits direct protocol fees')?'delivered':name.includes('failed sale refunds')?'refunded':'rejected';const provenance=captureProof();fs.writeFileSync(path.join(out,kind+'-'+outcome+'-boundaries.json'),JSON.stringify({schema:'tonswap.launchpad-canonical-boundaries.v1',network:'testnet',environment:'sandbox',vmVersion:15,gasPrice:'400',testName:name,nativeSourceInventory:sourceBefore,captureProof:provenance,transactions:rows},null,2)+'\n');});
afterAll(()=>{SmartContract.prototype.receiveMessage=original;captureProof();});

'use strict';
// Only the maintained driver selects these paths. Receipts never select code.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
function directory(name) {
  const value = process.env[name];
  assert(value && path.isAbsolute(value) && path.normalize(value) === value && fs.realpathSync(value) === value, name);
  assert(fs.lstatSync(value).isDirectory() && !fs.lstatSync(value).isSymbolicLink(), name);
  return value;
}
const nativeRoot = directory('TONSWAP_REFRESH_NATIVE_ROOT');
const outputRoot = directory('TONSWAP_REFRESH_OUTPUT_ROOT');
const family = process.env.TONSWAP_REFRESH_FAMILY;
assert(['factory', 'launchpad', 'options-protected', 'options-rejected'].includes(family), 'Unknown maintained adapter');
const workspace = path.dirname(nativeRoot);
assert(path.basename(nativeRoot) === 'tonswap_tolk');
assert(!outputRoot.startsWith(nativeRoot + path.sep), 'Evidence must be outside source');
module.exports = { nativeRoot, workspace, outputRoot, family };
